}

ParallelFor(0, shadowRayQueue->Size(),
                   [=] (int index) {
                       const ShadowRayWorkItem w = (*shadowRayQueue)[index];
                       bool hit = aggregate.IntersectP(w.ray, w.tMax);
                       RecordShadowRayResult(w, pixelSampleState, hit);
                   });

ParallelFor(0, shadowRayQueue->Size(),
            [=] (int index) {
                const ShadowRayWorkItem w = (*shadowRayQueue)[index];
                bool hit = aggregate.IntersectP(w.ray, w.tMax);
                RecordShadowRayResult(w, pixelSampleState, hit);
            });

void RecordShadowRayResult(const ShadowRayWorkItem w,
        SOA<PixelSampleState> *pixelSampleState, bool foundIntersection) {
    if (foundIntersection)
        return;
    SampledSpectrum Ld = w.Ld / (w.r_u + w.r_l).Average();
    SampledSpectrum Lpixel = pixelSampleState->L[w.pixelIndex];
    pixelSampleState->L[w.pixelIndex] = Lpixel + Ld;
}

